select tablename, policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'public' and tablename in ('services', 'service_blocks', 'invitations') order by tablename, cmd, policyname;
select c.relname as tabla, has_table_privilege('anon', c.oid, 'select') as anon_select, has_table_privilege('anon', c.oid, 'insert') as anon_insert, has_table_privilege('anon', c.oid, 'update') as anon_update, has_table_privilege('anon', c.oid, 'delete') as anon_delete from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname in ('services', 'service_blocks', 'invitations') order by 1;
do $$ declare sid uuid; mid uuid; bid uuid; iid uuid; adm text; lid text; r text := ''; n int; imp uuid := '00000000-0000-0000-0000-00000000dead'; begin select id into sid from public.services order by fecha desc limit 1; select id into mid from public.members limit 1; select id into bid from public.service_blocks limit 1; select id into iid from public.invitations limit 1; select m.email into adm from public.organization_members om join public.members m on m.id = om.person_id where om.role in ('owner', 'admin') and m.email is not null limit 1; select m.email into lid from public.team_members tm join public.members m on m.id = tm.member_id where tm.is_leader and m.email is not null and not exists (select 1 from public.organization_members om where om.person_id = tm.member_id and om.role in ('owner', 'admin')) limit 1; if sid is null or mid is null or bid is null or iid is null or adm is null or lid is null then raise exception 'Falta un servicio, una persona, un bloque, una invitación, un administrador o un líder que no sea administrador para probar'; end if;
set local role anon;
begin insert into public.services (fecha, titulo) values ('2099-12-31', 'prueba'); r := r || 'FALLO: anon insertó en services; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en services; '; end;
begin update public.services set titulo = titulo where id = imp; r := r || 'FALLO: anon pudo actualizar services; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza services; '; end;
begin delete from public.services where id = imp; r := r || 'FALLO: anon pudo borrar en services; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en services; '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9999, 'bloque', 'prueba'); r := r || 'FALLO: anon insertó en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en service_blocks; '; end;
begin update public.service_blocks set orden = orden where id = imp; r := r || 'FALLO: anon pudo actualizar service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza service_blocks; '; end;
begin delete from public.service_blocks where id = imp; r := r || 'FALLO: anon pudo borrar en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en service_blocks; '; end;
begin insert into public.invitations (service_id, member_id) values (sid, mid); r := r || 'FALLO: anon insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en invitations; '; when unique_violation then r := r || 'FALLO: anon pasó la seguridad en invitations (chocó con una fila existente); '; end;
begin update public.invitations set status = status where id = imp; r := r || 'FALLO: anon pudo actualizar invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza invitations; '; end;
begin delete from public.invitations where id = imp; r := r || 'FALLO: anon pudo borrar en invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en invitations; '; end;
select count(*) into n from public.services; r := r || 'OK: anon sigue leyendo services (' || n || '); ';
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', adm, 'role', 'authenticated')::text, true);
begin insert into public.services (fecha, titulo) values ('2099-12-31', 'prueba'); r := r || 'OK: el administrador inserta en services; '; exception when insufficient_privilege then r := r || 'FALLO: el administrador no pudo insertar en services; '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9999, 'bloque', 'prueba'); r := r || 'OK: el administrador inserta en service_blocks; '; exception when insufficient_privilege then r := r || 'FALLO: el administrador no pudo insertar en service_blocks; '; end;
delete from public.service_blocks where service_id = sid and orden = 9999; get diagnostics n = row_count; r := r || case when n = 1 then 'OK: el administrador borra en service_blocks; ' else 'FALLO: el administrador no borró en service_blocks (' || n || ' filas); ' end;
update public.services set titulo = titulo where id = sid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: ni el administrador actualiza services desde el navegador; ' else 'FALLO: el administrador actualizó services; ' end;
begin insert into public.invitations (service_id, member_id) values (sid, mid); r := r || 'FALLO: el administrador insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: el administrador no inserta en invitations desde el navegador; '; when unique_violation then r := r || 'FALLO: el administrador pasó la seguridad en invitations; '; end;
update public.invitations set status = status where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el administrador no actualiza invitations; ' else 'FALLO: el administrador actualizó invitations; ' end;
delete from public.invitations where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el administrador no borra invitations; ' else 'FALLO: el administrador borró invitations; ' end;
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', lid, 'role', 'authenticated')::text, true);
begin insert into public.services (fecha, titulo) values ('2099-12-31', 'prueba'); r := r || 'FALLO: el líder insertó en services; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en services; '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9999, 'bloque', 'prueba'); r := r || 'FALLO: el líder insertó en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en service_blocks; '; end;
begin insert into public.invitations (service_id, member_id) values (sid, mid); r := r || 'FALLO: el líder insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en invitations; '; when unique_violation then r := r || 'FALLO: el líder pasó la seguridad en invitations; '; end;
update public.services set titulo = titulo where id = sid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no actualiza services; ' else 'FALLO: el líder actualizó services; ' end;
delete from public.service_blocks where id = bid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no borra en service_blocks; ' else 'FALLO: el líder borró en service_blocks; ' end;
update public.invitations set status = status where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no actualiza invitations; ' else 'FALLO: el líder actualizó invitations; ' end;
reset role;
raise exception 'Resultado (se deshace todo): %', r; end $$;
